"use client"

import { useState } from "react"

export default function CreatePetition() {
  const [form, setForm] = useState({
    title: "",
    description: "",
    category: "",
    location: "",
  })

  return (
<div className="min-h-screen relative flex items-center justify-center overflow-hidden bg-black">
  
  {/* Animated circles */}
   <div className="absolute w-96 h-96 bg-purple-500 rounded-full blur-3xl opacity-30 animate-pulse top-10 left-10"></div>
   <div className="absolute w-96 h-96 bg-blue-500 rounded-full blur-3xl opacity-30 animate-pulse bottom-10 right-10"></div>
   <div className="absolute w-96 h-96 bg-pink-500 rounded-full blur-3xl opacity-30 animate-pulse top-1/2 left-1/2"></div>

  {/* Your Form Card */}
   <div className="relative z-10 w-full max-w-2xl bg-white/10 backdrop-blur-lg rounded-3xl p-10 shadow-2xl">
        
        <h1 className="text-3xl font-bold text-center mb-8 text-gray-800">
          ✨ Create Petition
        </h1>

        {/* Title */}
        <div className="mb-6">
          <label className="block font-semibold mb-2 text-gray-700">
            Petition Title
          </label>
          <input
            type="text"
            placeholder="Enter petition title"
            className="w-full p-4 bg-gray-100 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-purple-500 focus:bg-white transition-all duration-300"
          />
        </div>

        {/* Description */}
        <div className="mb-6">
          <label className="block font-semibold mb-2 text-gray-700">
            Description
          </label>
          <textarea
            placeholder="Enter detailed description"
            rows={4}
            className="w-full p-4 bg-gray-100 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-purple-500 focus:bg-white transition-all duration-300 resize-none"
          />
        </div>

        {/* Category */}
        <div className="mb-6">
          <label className="block font-semibold mb-2 text-gray-700">
            Category
          </label>
          <select
            className="w-full p-4 bg-gray-100 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-purple-500 focus:bg-white transition-all duration-300"
          >
            <option>Select Category</option>
            <option>Environment</option>
            <option>Education</option>
            <option>Health</option>
            <option>Infrastructure</option>
          </select>
        </div>

        {/* Location */}
        <div className="mb-8">
          <label className="block font-semibold mb-2 text-gray-700">
            Location
          </label>
          <input
            type="text"
            placeholder="Enter location"
            className="w-full p-4 bg-gray-100 rounded-xl border border-gray-300 focus:outline-none focus:ring-2 focus:ring-purple-500 focus:bg-white transition-all duration-300"
          />
        </div>

        {/* Button */}
        <button className="w-full py-4 bg-gradient-to-r from-purple-600 to-indigo-600 text-white font-semibold rounded-xl shadow-lg hover:scale-105 hover:shadow-xl transition-all duration-300">
          🚀 Submit Petition
        </button>
      </div>
    </div>
  )
}